<?php
declare(strict_types=1);

require_once __DIR__ . '/document_library_health.php';
require_once __DIR__ . '/admin_accounts.php';
require_once __DIR__ . '/admin_audit.php';

function portal_render_admin_overview(array $admin): void { $c='<section class="hero admin-console"><p class="eyebrow">ADMINISTRATION</p><h1>管理後台</h1><p>管理帳號、檢查文件庫健康狀態、受控同步與查閱安全及管理稽核紀錄。</p><div class="hero-actions"><a class="primary-button" href="'.portal_url('admin_users').'">帳號管理</a><a class="secondary-button" href="'.portal_url('admin_library_health').'">文件庫健康</a><a class="secondary-button" href="'.portal_url('admin_sync').'">同步管理</a><a class="secondary-button" href="'.portal_url('admin_audit').'">稽核紀錄</a><a class="secondary-button" href="'.portal_url('documents').'">開啟文件庫</a></div></section>';portal_render_page('管理後台',$c,$admin,false,'admin-console-page'); }
function portal_render_admin_users_page(array $admin,PDO $database): void { $rows='';$forms='';foreach(portal_list_admin_accounts($database) as $a){$id=(int)$a['user_id'];$rows.='<tr><td>'.portal_e((string)$a['username']).'</td><td>'.portal_e((string)$a['display_name']).'</td><td>'.portal_e((string)$a['role_code']).'</td><td>'.portal_e(portal_admin_login_mode_label((string)$a['login_mode'])).'</td><td>'.((int)$a['is_enabled']?'啟用':'停用').'</td><td><a class="secondary-button compact-button" href="#account-'.$id.'">設定</a></td></tr>';$forms.='<details id="account-'.$id.'" class="panel"><summary>設定 '.portal_e((string)$a['username']).'</summary><form method="post" action="'.portal_url('admin_account_update').'" class="admin-form">'.portal_csrf_field().'<input type="hidden" name="user_id" value="'.$id.'"><label>顯示名稱<input name="display_name" value="'.portal_e((string)$a['display_name']).'" required></label><label>角色<select name="role_code"><option value="reader"'.($a['role_code']==='reader'?' selected':'').'>reader</option><option value="admin"'.($a['role_code']==='admin'?' selected':'').'>admin</option></select></label><label>登入方式<select name="login_mode"><option value="local_only">僅本機帳密</option><option value="google_only"'.($a['login_mode']==='google_only'?' selected':'').'>僅 Google</option><option value="local_and_google"'.($a['login_mode']==='local_and_google'?' selected':'').'>本機與 Google</option></select></label><label>預綁 Google Email<input type="email" name="google_email" value="'.portal_e((string)($a['google_email']??'')).'"></label><label><input type="checkbox" name="is_enabled" value="1"'.((int)$a['is_enabled']?' checked':'').'> 啟用帳號</label><button class="primary-button" type="submit">預覽變更</button></form><form method="post" action="'.portal_url('admin_account_reset_password').'" class="admin-form">'.portal_csrf_field().'<input type="hidden" name="user_id" value="'.$id.'"><label>新初始密碼（至少 16 字元）<input type="password" name="new_password" minlength="16" required></label><button class="secondary-button" type="submit">預覽重設密碼</button></form></details>';}$c='<a class="back-link" href="'.portal_url('admin').'">← 返回管理總覽</a><section class="hero admin-console"><h1>帳號管理</h1><p>帳號只能建立、調整、停用或重設；不可永久刪除。每一項寫入都須先預覽再確認。</p></section><section class="panel"><h2>現有帳號</h2><div class="table-scroll"><table><thead><tr><th>帳號</th><th>名稱</th><th>角色</th><th>登入方式</th><th>狀態</th><th></th></tr></thead><tbody>'.$rows.'</tbody></table></div></section>'.$forms.'<section class="panel"><h2>新增帳號</h2><form method="post" action="'.portal_url('admin_account_create').'" class="admin-form">'.portal_csrf_field().'<label>帳號<input name="username" required></label><label>顯示名稱<input name="display_name" required></label><label>角色<select name="role_code"><option value="reader">reader</option><option value="admin">admin</option></select></label><label>登入方式<select name="login_mode"><option value="local_only">僅本機帳密</option><option value="google_only">僅 Google</option><option value="local_and_google">本機與 Google</option></select></label><label>預綁 Google Email<input type="email" name="google_email"></label><label>初始密碼<input name="password" type="password"></label><button class="primary-button" type="submit">預覽新增</button></form></section>';portal_render_page('帳號管理',$c,$admin,false,'admin-console-page'); }
function portal_health_payload():array{$r=portal_document_library_health_report((string)portal_config()['document_root']);return ['status'=>(string)$r['status'],'file_count'=>number_format((int)$r['file_count']).' 件','directory_count'=>number_format((int)$r['directory_count']).' 個','total_bytes'=>number_format((int)$r['total_bytes']).' B','exception_count'=>number_format((int)$r['exception_count']).' 件'];}
function portal_render_admin_library_health_page(array $admin):void{$r=portal_health_payload();$c='<a class="back-link" href="'.portal_url('admin').'">← 返回管理總覽</a><section class="hero admin-console"><h1>文件庫健康</h1><p>此頁僅讀取檔案系統中繼資料；每 60 秒原地重新查詢，不會同步或修改文件。</p></section><section class="panel" data-health-poll-url="'.portal_e(portal_url('admin_library_health_data')).'"><dl class="admin-health-summary"><dt>掃描狀態</dt><dd data-health="status">'.portal_e($r['status']).'</dd><dt>檔案</dt><dd data-health="file_count">'.portal_e($r['file_count']).'</dd><dt>資料夾</dt><dd data-health="directory_count">'.portal_e($r['directory_count']).'</dd><dt>總容量</dt><dd data-health="total_bytes">'.portal_e($r['total_bytes']).'</dd><dt>例外</dt><dd data-health="exception_count">'.portal_e($r['exception_count']).'</dd></dl></section>';portal_render_page('文件庫健康',$c,$admin,false,'admin-console-page');}
function portal_handle_admin_library_health_data(array $admin):void{header('Content-Type: application/json; charset=UTF-8');echo json_encode(portal_health_payload(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function portal_sync_results_html(array $items,int $viewerId=0):string{$rows='';foreach($items as $item){$id=portal_e((string)$item['request_id']);$state=portal_e((string)$item['status']);$time=portal_e((string)$item['updated_at']);$direction=portal_e(portal_sync_direction_label((string)$item['direction']));$metrics=(bool)($item['metrics_recorded']??false);$owned=(int)($item['requested_by']??0)===$viewerId;$counts=$metrics?'新增 '.number_format((int)($item['add_count']??0)).'／更新 '.number_format((int)($item['update_count']??0)).'／刪除 '.number_format((int)($item['delete_count']??0)).'／衝突 '.number_format((int)($item['conflict_count']??0)).'／拒絕 '.number_format((int)($item['access_denied_count']??0)):'尚無可驗證統計；等待服務完成預覽。';$rows.='<li><strong>'.$state.'</strong> · '.$direction.' · '.$time.'<br><span>'.$counts.'</span><br><code>'.$id.'</code>';if(portal_sync_preview_confirmable($item,$viewerId))$rows.='<form method="post" action="'.portal_url('admin_sync_confirm').'">'.portal_csrf_field().'<input type="hidden" name="direction" value="'.portal_e((string)$item['direction']).'"><input type="hidden" name="preview_id" value="'.portal_e((string)$item['preview_id']).'"><button class="primary-button" type="submit">確認執行</button></form>';if($owned&&in_array((string)($item['status']??''),['queued','running'],true))$rows.='<form method="post" action="'.portal_url('admin_sync_cancel').'">'.portal_csrf_field().'<input type="hidden" name="request_id" value="'.$id.'"><button class="secondary-button" type="submit">取消同步</button></form>';$rows.='</li>';}return $rows?:'<li>目前沒有同步請求或結果。</li>';}
function portal_sync_selected_direction():string{try{return portal_sync_direction((string)($_GET['sync_direction']??'drive_to_library'));}catch(Throwable){return 'drive_to_library';}}
function portal_render_admin_sync_page_legacy(array $admin,PDO $database):void{$status=portal_sync_status();$rows=portal_sync_results_html((array)$status['items'],(int)$admin['user_id']);$direction=portal_sync_selected_direction();$c='<a class="back-link" href="'.portal_url('admin').'">← 返回管理總覽</a><section class="hero admin-console"><h1>同步管理</h1><p>僅管理員可經預覽及確認發出同步請求；網站不直接執行 CLI。狀態每 5 秒原地更新。</p></section><section class="panel sync-panel" data-sync-panel data-sync-poll-url="'.portal_e(portal_url('admin_sync_data')).'"><form method="post" action="'.portal_url('admin_sync_request').'" data-sync-request-form>'.portal_csrf_field().'<label>同步方向<select name="direction"><option value="drive_to_library"'.($direction==='drive_to_library'?' selected':'').'>Google Drive → 網站 document-library</option><option value="library_to_drive"'.($direction==='library_to_drive'?' selected':'').'>網站 document-library → Google Drive</option><option value="two_way"'.($direction==='two_way'?' selected':'').'>雙向同步</option></select></label><button class="primary-button" type="submit" data-sync-submit>產生同步預覽</button><p role="status" aria-live="polite" data-sync-feedback></p></form><p data-sync-status>服務狀態：'.portal_e((string)$status['status']).'</p><p class="helper-text" data-sync-last-updated>最後更新：頁面載入時</p></section><section class="panel"><h2>同步預覽結果與執行狀態</h2><p>僅會顯示受限的狀態、方向與時間；不會將服務設定、路徑或 CLI 輸出暴露到網站。</p><ul data-sync-results>'.$rows.'</ul></section>';portal_render_page('同步管理',$c,$admin,false,'admin-console-page');}
function portal_sync_history_cursor_from_get(array $query):?array{$time=(string)($query['history_cursor_time']??'');$id=(string)($query['history_cursor_id']??'');if($time===''&&$id==='')return null;if(!preg_match('/^[a-f0-9]{32}$/',$id))return null;try{new DateTimeImmutable($time);}catch(Throwable){return null;}return ['updated_at'=>$time,'request_id'=>$id];}
function portal_sync_history_parameters(array $filters,?array $cursor=null):array{$q=[];foreach(['status'=>'history_status','direction'=>'history_direction','start_date'=>'history_start_date','end_date'=>'history_end_date','request_id_prefix'=>'history_request_id_prefix'] as $key=>$name)if((string)$filters[$key]!=='')$q[$name]=(string)$filters[$key];if($cursor!==null){$q['history_cursor_time']=(string)$cursor['updated_at'];$q['history_cursor_id']=(string)$cursor['request_id'];}return $q;}
function portal_sync_management_view(array $status,int $viewerId,array $query):array{$filters=portal_sync_history_query(['status'=>$query['history_status']??'','direction'=>$query['history_direction']??'','start_date'=>$query['history_start_date']??'','end_date'=>$query['history_end_date']??'','request_id_prefix'=>$query['history_request_id_prefix']??'']);$cursor=portal_sync_history_cursor_from_get($query);$items=(array)($status['items']??[]);$operation=portal_sync_operation_candidate($items,$viewerId);$history=array_values(array_filter($items,static fn(array $item):bool=>(string)($item['request_id']??'')!==(string)($operation['request_id']??'')));$page=portal_sync_history_page($history,$filters,$cursor,5);return ['operation'=>$operation,'history'=>$page,'filters'=>$filters,'cursor'=>$cursor,'history_live'=>$cursor===null&&$filters===['status'=>'','direction'=>'','start_date'=>'','end_date'=>'','request_id_prefix'=>'']];}
function portal_sync_status_label(string $status):string{return match($status){'preview_ready'=>'預覽完成','queued'=>'等待處理','running'=>'執行中','success'=>'同步成功','completed_with_attention'=>'已完成（需注意）','failed'=>'同步失敗','aborted_unverified'=>'已中止（未驗證）',default=>'狀態不明'};}
function portal_sync_item_details_html(array $item):string{$metrics=(bool)($item['metrics_recorded']??false);$counts=$metrics?'新增 '.number_format((int)($item['add_count']??0)).'／更新 '.number_format((int)($item['update_count']??0)).'／刪除 '.number_format((int)($item['delete_count']??0)).'／衝突 '.number_format((int)($item['conflict_count']??0)).'／拒絕 '.number_format((int)($item['access_denied_count']??0)):'尚無可驗證統計；等待服務完成預覽。';return '<strong>'.portal_e(portal_sync_status_label((string)$item['status'])).'</strong> · '.portal_e(portal_sync_direction_label((string)$item['direction'])).' · '.portal_e((string)$item['updated_at']).'<br><span>'.$counts.'</span><br><code>'.portal_e((string)$item['request_id']).'</code>';}
function portal_sync_current_operation_html(?array $item,int $viewerId):string{if($item===null)return '<p>目前沒有可操作的同步項目。</p>';$html='<div class="sync-current-item">'.portal_sync_item_details_html($item);$owned=(int)($item['requested_by']??0)===$viewerId;if(portal_sync_preview_confirmable($item,$viewerId))$html.='<form method="post" action="'.portal_url('admin_sync_confirm').'">'.portal_csrf_field().'<input type="hidden" name="direction" value="'.portal_e((string)$item['direction']).'"><input type="hidden" name="preview_id" value="'.portal_e((string)$item['preview_id']).'"><button class="primary-button" type="submit">確認執行</button></form>';if($owned&&in_array((string)($item['status']??''),['queued','running'],true))$html.='<form method="post" action="'.portal_url('admin_sync_cancel').'">'.portal_csrf_field().'<input type="hidden" name="request_id" value="'.portal_e((string)$item['request_id']).'"><button class="secondary-button" type="submit">取消同步</button></form>';return $html.'</div>';}
function portal_sync_history_html(array $view):string{$page=$view['history'];$rows='';foreach((array)$page['items'] as $item)$rows.='<li>'.portal_sync_item_details_html($item).'</li>';$summary='符合條件共 '.number_format((int)$page['total_count']).' 筆';if($rows==='')$rows='<li>找不到符合條件的同步歷史紀錄。</li>';$more='';if($page['has_more'])$more='<a class="secondary-button compact-button" href="'.portal_e(portal_url('admin_sync',portal_sync_history_parameters($view['filters'],$page['next_cursor']))).'">更多歷史紀錄</a>';$latest=$view['cursor']===null?'':' <a href="'.portal_e(portal_url('admin_sync')).'">返回最新紀錄</a>';return '<p class="helper-text">'.$summary.$latest.'</p><ul class="sync-history-list">'.$rows.'</ul>'.$more;}
function portal_sync_history_filters_html(array $filters):string{$select=function(string $name,array $options,string $selected):string{$html='<select name="'.$name.'"><option value="">全部</option>';foreach($options as $value=>$label)$html.='<option value="'.portal_e($value).'"'.($value===$selected?' selected':'').'>'.portal_e($label).'</option>';return $html.'</select>';};$isActive=$filters!==['status'=>'','direction'=>'','start_date'=>'','end_date'=>'','request_id_prefix'=>''];return '<details class="sync-history-query"'.($isActive?' open':'').'><summary>查詢條件</summary><form method="get" action="'.portal_url('admin_sync').'" class="sync-history-filters"><input type="hidden" name="action" value="admin_sync"><label>狀態'.$select('history_status',['preview_ready'=>'預覽完成','queued'=>'等待處理','running'=>'執行中','success'=>'同步成功','completed_with_attention'=>'已完成（需注意）','failed'=>'同步失敗','aborted_unverified'=>'已中止（未驗證）'],(string)$filters['status']).'</label><label>方向'.$select('history_direction',['drive_to_library'=>'Google Drive → 網站 document-library','library_to_drive'=>'網站 document-library → Google Drive','two_way'=>'雙向同步'],(string)$filters['direction']).'</label><label>起始日期（台北）<input type="date" name="history_start_date" value="'.portal_e((string)$filters['start_date']).'"></label><label>結束日期（台北）<input type="date" name="history_end_date" value="'.portal_e((string)$filters['end_date']).'"></label><label>Request ID<input name="history_request_id_prefix" maxlength="32" pattern="[a-f0-9]{1,32}" value="'.portal_e((string)$filters['request_id_prefix']).'"></label><button class="secondary-button" type="submit">查詢</button><a class="secondary-button compact-button" href="'.portal_url('admin_sync').'">清除條件</a></form></details>';}
function portal_render_admin_sync_page(array $admin,PDO $database):void{$status=portal_sync_status();$view=portal_sync_management_view($status,(int)$admin['user_id'],$_GET);$direction=portal_sync_selected_direction();$poll=portal_url('admin_sync_data',portal_sync_history_parameters($view['filters'],$view['cursor']));$c='<a class="back-link" href="'.portal_url('admin').'">← 返回管理總覽</a><section class="hero admin-console"><h1>同步管理</h1><p>僅管理員可經預覽及確認發出同步請求；網站不直接執行 CLI。狀態每 5 秒原地更新。</p></section><div class="sync-action-grid"><section class="panel sync-panel" data-sync-panel data-sync-history-live="'.($view['history_live']?'1':'0').'" data-sync-poll-url="'.portal_e($poll).'"><form method="post" action="'.portal_url('admin_sync_request').'" data-sync-request-form>'.portal_csrf_field().'<label>同步方向<select name="direction"><option value="drive_to_library"'.($direction==='drive_to_library'?' selected':'').'>Google Drive → 網站 document-library</option><option value="library_to_drive"'.($direction==='library_to_drive'?' selected':'').'>網站 document-library → Google Drive</option><option value="two_way"'.($direction==='two_way'?' selected':'').'>雙向同步</option></select></label><button class="primary-button" type="submit" data-sync-submit>產生同步預覽</button><p role="status" aria-live="polite" data-sync-feedback></p></form><p data-sync-status>服務狀態：'.portal_e((string)$status['status']).'</p><p class="helper-text" data-sync-last-updated>最後更新：頁面載入時</p></section><section class="panel sync-current-panel"><h2>目前同步作業</h2><div data-sync-current-operation>'.portal_sync_current_operation_html($view['operation'],(int)$admin['user_id']).'</div></section></div><section class="panel"><h2>同步歷史紀錄</h2><p>所有日期以 Asia/Taipei（UTC+8）計算；歷史僅供查閱，不提供同步動作。</p>'.portal_sync_history_filters_html($view['filters']).'<div data-sync-history>'.portal_sync_history_html($view).'</div></section>';portal_render_page('同步管理',$c,$admin,false,'admin-console-page');}
function portal_handle_admin_sync_data(array $admin):void{header('Content-Type: application/json; charset=UTF-8');$data=portal_sync_status();$view=portal_sync_management_view($data,(int)$admin['user_id'],$_GET);$data['current_html']=portal_sync_current_operation_html($view['operation'],(int)$admin['user_id']);$data['history_html']=$view['history_live']?portal_sync_history_html($view):'';$data['history_live']=$view['history_live'];unset($data['items']);echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function portal_render_admin_sync_error(array $admin):void{http_response_code(400);portal_render_page('同步請求未送出','<a class="back-link" href="'.portal_url('admin_sync').'">← 返回同步管理</a><section class="panel"><h1>同步請求未送出</h1><p>請重新整理同步管理頁面後再試；系統未執行任何同步變更。</p></section>',$admin);exit;}
function portal_handle_admin_sync_request(PDO $database,array $admin):void{if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}try{portal_assert_csrf();$direction=portal_sync_direction((string)($_POST['direction']??''));$id=portal_sync_request_create($database,$admin,$direction,'preview');}catch(Throwable){portal_render_admin_sync_error($admin);}portal_flash_set('success','同步預覽請求已送出：'.$id);header('Location: '.portal_url('admin_sync',['sync_direction'=>$direction]),true,303);}
function portal_handle_admin_sync_confirm(PDO $database,array $admin):void{if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}try{portal_assert_csrf();$id=portal_sync_request_create($database,$admin,(string)($_POST['direction']??''),'execute',(string)($_POST['preview_id']??''));}catch(Throwable){portal_render_admin_sync_error($admin);}portal_flash_set('success','同步執行請求已送出：'.$id);header('Location: '.portal_url('admin_sync'),true,303);}
function portal_handle_admin_sync_cancel(PDO $database,array $admin):void{if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}try{portal_assert_csrf();portal_sync_request_cancel($database,$admin,(string)($_POST['request_id']??''));}catch(Throwable){portal_render_admin_sync_error($admin);}portal_flash_set('success','取消要求已送出。');header('Location: '.portal_url('admin_sync'),true,303);}
function portal_render_admin_audit_page(array $admin,PDO $database):void{$rows='';foreach(portal_list_admin_management_audit($database,$_GET) as $e)$rows.='<tr><td>'.portal_e((string)$e['occurred_at']).'</td><td>'.portal_e((string)$e['event_type']).'</td><td>'.portal_e((string)($e['actor_user_id']??'—')).'</td><td>'.portal_e((string)($e['target_user_id']??'—')).'</td><td>'.portal_e((string)$e['summary_json']).'</td></tr>';$c='<a class="back-link" href="'.portal_url('admin').'">← 返回管理總覽</a><section class="hero admin-console"><h1>稽核紀錄</h1><p>只讀、追加式、雜湊鏈保護的管理與安全紀錄。</p></section><section class="panel table-scroll"><table><thead><tr><th>時間 UTC</th><th>事件</th><th>執行者</th><th>目標</th><th>安全摘要</th></tr></thead><tbody>'.$rows.'</tbody></table></section>';portal_render_page('稽核紀錄',$c,$admin,false,'admin-console-page');}
function portal_render_admin_account_confirmation(array $admin,array $pending):void{$kind=(string)$pending['kind'];$input=(array)$pending['input'];$summary=$kind==='reset'?['operation'=>'重設密碼','target_user_id'=>(string)$input['user_id'],'new_password'=>'已提供，不顯示']:($kind==='create'?array_merge(array_diff_key($input,['staged_password_hash'=>true]),['initial_password'=>'已提供，不顯示']):$input);$rows='';foreach($summary as $k=>$v)$rows.='<tr><th>'.portal_e((string)$k).'</th><td>'.portal_e(is_scalar($v)?(string)$v:json_encode($v,JSON_UNESCAPED_UNICODE)).'</td></tr>';$c='<a class="back-link" href="'.portal_url('admin_users').'">← 返回帳號管理</a><section class="panel"><p class="eyebrow">CONFIRM ACCOUNT CHANGE</p><h1>確認帳號變更</h1><p>old/new impact summary：以下是即將套用的安全影響摘要。按下確認後才會寫入 SQLite 並立即讀回。</p><table><tbody>'.$rows.'</tbody></table><form method="post" action="'.portal_url('admin_account_confirm').'">'.portal_csrf_field().'<button class="primary-button" type="submit">確認套用</button></form></section>';portal_render_page('確認帳號變更',$c,$admin,false,'admin-console-page');}
function portal_stage_admin_account_change(array $admin,string $kind,array $input):void{if($kind==='create'||$kind==='reset'){ $password=(string)($kind==='create'?($input['password']??''):($input['new_password']??'')); if(strlen($password)<16||strlen($password)>1024)throw new RuntimeException('本機密碼至少須為 16 個字元。');$input['staged_password_hash']=password_hash($password,PASSWORD_DEFAULT);if($kind==='create')unset($input['password']);else unset($input['new_password']);}$_SESSION['pending_account_change']=['kind'=>$kind,'input'=>$input,'actor_user_id'=>(int)$admin['user_id'],'created_at'=>time()];portal_render_admin_account_confirmation($admin,$_SESSION['pending_account_change']);}
function portal_handle_admin_account_create(PDO $database,array $admin):void{if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}portal_assert_csrf();portal_stage_admin_account_change($admin,'create',$_POST);}
function portal_handle_admin_account_update(PDO $database,array $admin):void{if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}portal_assert_csrf();$_POST['is_enabled']=isset($_POST['is_enabled'])?'1':'0';portal_stage_admin_account_change($admin,'update',$_POST);}
function portal_handle_admin_account_reset_password(PDO $database,array $admin):void{if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}portal_assert_csrf();portal_stage_admin_account_change($admin,'reset',['user_id'=>(int)($_POST['user_id']??0),'new_password'=>(string)($_POST['new_password']??'')]);}
function portal_handle_admin_account_confirmation(PDO $database,array $admin):void{if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}try{portal_assert_csrf();$p=$_SESSION['pending_account_change']??null;if(!is_array($p)||(int)($p['actor_user_id']??0)!==(int)$admin['user_id']||time()-(int)($p['created_at']??0)>600)throw new RuntimeException('確認資料已失效。');portal_state_verify_audit_chain($database);$input=(array)$p['input'];if($p['kind']==='create')portal_create_account($database,(int)$admin['user_id'],$input);elseif($p['kind']==='update')portal_update_account($database,(int)$admin['user_id'],(int)($input['user_id']??0),$input);elseif($p['kind']==='reset')portal_sqlite_reset_password_with_hash($database,(int)$admin['user_id'],(int)$input['user_id'],(string)$input['staged_password_hash']);else throw new RuntimeException('確認資料無效。');unset($_SESSION['pending_account_change']);portal_flash_set('success','帳號變更已套用、稽核並讀回。');}catch(Throwable){portal_flash_set('error','帳號變更未套用；請重新預覽並確認。');}header('Location: '.portal_url('admin_users'),true,303);}
